(() => {'use strict';
const $=s=>document.querySelector(s),e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#newChoices').innerHTML=MediaInfoKurzprojekte.map(p=>`<article class="choicecard"><div class="projectvisual ${p.color}"><img src="assets/${p.id==='bildausschnitt'?'parkbild.jpg':p.id+'bild.svg'}" alt="" loading="lazy"><span class="visualbadge">${e(p.subtitle)}</span>${p.id==='bildausschnitt'?'<span class="cropoutline" aria-hidden="true"></span>':''}</div><div class="choicebody"><p class="kicker">${e(p.duration)} · ${e(p.category)}</p><h3>${e(p.title)}</h3><p>${e(p.hook)}</p><div class="resultbox"><span>Das entsteht</span><p>${e(p.product)}</p></div><p class="muted">${e(p.extension)}</p><a class="a-button" href="projekt.html?thema=${p.id}">Auftrag öffnen <span aria-hidden="true">→</span></a></div></article>`).join('');
const old=[['tutorial','Erklär’s besser','Eine kleine digitale Fähigkeit verständlich erklären. Heute die Bildanleitung wählen.','45–65 Min.','Kurze Etappe: zwei eigene Bildschritte erstellen.'],['cockpit','Mein digitales Cockpit','Eine persönliche Startseite in OneNote mit Aufgaben, Terminen und Links aufbauen.','40–55 Min.','Kurze Etappe: vier Bereiche anlegen und drei Aufgaben eintragen.'],['dokumente','Alles in einer PDF','Drei Übungsseiten zu einem lesbaren, richtig sortierten Dossier zusammenstellen.','35–50 Min.','Kurze Etappe: Seiten ordnen und die erste Seite erfassen.'],['faktencheck','Echt oder Fake?','Eine Behauptung prüfen und Informationen aus zwei Quellen vergleichen.','45–60 Min.','Kurze Etappe: eine Quelle lesen und eine wichtige Information mit Link notieren.'],['lifehacks','Fünf Tricks, die bleiben','Digitale Tipps selbst testen und verständlich festhalten.','45–65 Min.','Kurze Etappe: einen Tipp testen und vollständig erklären. Das ganze Projekt umfasst fünf Tipps.']];
$('#oldChoices').innerHTML=old.map(([id,t,d,time,short])=>`<article class="choicecard"><div class="projectvisual existing"><img src="assets/projects/media/${id}-02.svg" alt="" loading="lazy"></div><div class="choicebody"><p class="kicker">${time} · vollständiges Projekt</p><h3>${t}</h3><p>${d}</p><p class="muted">${short}</p><a class="a-button outline" href="projekte.html#${id}">Projekt ansehen →</a></div></article>`).join('');
const advice={10:'Beginnen Sie mit einer einzelnen Nachricht im Projekt «Würden Sie reagieren?». Bearbeiten Sie die Entscheidung, die Textstelle und Ihren nächsten Schritt. Auch ein anderer sinnvoller Anfang ist erlaubt. Planen Sie die letzten fünf Minuten fürs Sichern ein.',25:'Die vier kurzen Projekte passen gut. Beginnen Sie mit dem Grundauftrag und sichern Sie Ihren Stand, auch wenn noch etwas offen ist. Am schnellsten gelingt ein vollständiger Grundauftrag bei «Würden Sie reagieren?».',45:'Bearbeiten Sie einen kurzen Grundauftrag und danach dessen Zusatzauftrag. Oder beginnen Sie eines der fünf grösseren Projekte. Prüfen und sichern Sie am Ende Ihr Ergebnis.',60:'Sie haben Zeit für einen Grundauftrag mit Vertiefung oder ein grösseres Projekt. Wenn Sie fertig sind, dürfen Sie ein weiteres Thema wählen. Beenden Sie zuerst Ihre aktuelle Aufgabe und sichern Sie das Ergebnis.'};
document.querySelectorAll('[data-time]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-time]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#timeAdvice').textContent=advice[b.dataset.time];}));
$('#fontToggle').addEventListener('click',()=>{const on=document.body.classList.toggle('large');$('#fontToggle').setAttribute('aria-pressed',String(on));});
})();
